// Repro for bucket B1 (data_byte_fail): the eight data bits must be sent
// least significant first. Checks only the data bits of frames sent from
// idle; parity and stop timing are not checked here.
`timescale 1ns / 1ps
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer    checks = 0;
    integer    failed = 0;
    integer    ncount = 0;
    integer    i;
    reg        v;
    reg        verdict_done = 1'b0;
    reg [8*96-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    // Advance to the target-th clock negedge after the start-bit edge.
    task advance_to(input integer target);
        begin
            while (ncount < target) begin
                @(negedge clk);
                ncount = ncount + 1;
            end
        end
    endtask

    // Request a frame from idle; return at the start bit's falling edge on tx.
    task begin_frame(input [7:0] b, input hold_start);
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(negedge tx);
            if (!hold_start) start = 1'b0;
            ncount = 0;
        end
    endtask

    // Sample tx at the centre of bit k (0 = start, 1..8 = data, 9 = parity, 10 = stop).
    task sample_bit(input integer k);
        begin
            advance_to(k * CPB + CPB / 2);
            v = tx;
        end
    endtask

    task verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("TB_VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
                $finish;
            end
        end
    endtask

    task send_and_check_data(input [7:0] b);
        begin
            begin_frame(b, 1'b0);
            for (i = 0; i < 8; i = i + 1) begin
                sample_bit(i + 1);
                checks = checks + 1;
                if (v !== b[i]) begin
                    failed = failed + 1;
                    $display("CHECK data_lsb_first FAIL byte=%h bit=%0d got=%b expected=%b", b, i, v, b[i]);
                end
            end
            advance_to(14 * CPB);
        end
    endtask

    initial begin
        #500000;
        $display("CHECK watchdog FAIL: no verdict before timeout");
        failed = failed + 1;
        verdict;
    end

    initial begin
        if (!$value$plusargs("nonce=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
                nonce = "unset";
        rst = 1'b1;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (2 * CPB) @(negedge clk);

        send_and_check_data(8'h01);
        send_and_check_data(8'hB2);
        send_and_check_data(8'h0F);
        send_and_check_data(8'h80);

        if (failed == 0) $display("CHECK data_lsb_first PASS");
        verdict;
    end
endmodule
=== END FILE ===

