// Repro for bucket B3 (frame_period_fail): the stop bit must last a full
// CLKS_PER_BIT cycles, so with start held high the next frame's start bit
// cannot begin before 11 bit-times after the previous start bit. Checks only
// the stop-bit window; data and parity values are not checked here.
`timescale 1ns / 1ps
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
