    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    task advance_to(input integer target);
        begin
            while (ncount < target) begin
                @(negedge clk);
                ncount = ncount + 1;
            end
        end
    endtask

    task begin_frame(input [7:0] b, input hold_start);
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(negedge tx);
            if (!hold_start) start = 1'b0;
            ncount = 0;
        end
    endtask

    task verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("TB_VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
                $finish;
            end
        end
    endtask

    initial begin
        #500000;
        $display("CHECK watchdog FAIL: no verdict before timeout");
        failed = failed + 1;
        verdict;
    end

    initial begin
        if (!$value$plusargs("nonce=%s", nonce))
            if (!$value$plusargs("NONCE=%s", nonce))
                nonce = "unset";
        rst = 1'b1;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (2 * CPB) @(negedge clk);

        // Hold start high: the next frame is requested as soon as the
        // transmitter is free, so a short stop bit lets it start early.
        begin_frame(8'h55, 1'b1);
        for (i = 10 * CPB + 1; i <= 11 * CPB; i = i + 1) begin
            advance_to(i);
            checks = checks + 1;
            if (tx !== 1'b1) begin
                failed = failed + 1;
                $display("CHECK stop_bit_length FAIL stop-bit cycle=%0d of %0d tx=%b expected=1",
                         i - 10 * CPB - 1, CPB, tx);
            end
        end
        @(negedge clk);
        start = 1'b0;
        repeat (16 * CPB) @(negedge clk);

        if (failed == 0) $display("CHECK stop_bit_length PASS");
        verdict;
    end
endmodule
=== END FILE ===

