// Repro for bucket B2 (parity_bit_fail): the parity bit must be even parity,
// i.e. equal to ^data, so the count of ones over data and parity is even.
// Checks only the parity bit; bit order and stop timing are not checked here.
`timescale 1ns / 1ps
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer    checks = 0;
    integer    failed = 0;
    integer    ncount = 0;
    reg        v;
    reg        verdict_done = 1'b0;
    reg [8*128-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    // Obtain the run nonce: a macro if defined, overridden by any known plusarg.
    task get_nonce;
        begin
            nonce = "unset";
`ifdef TB_NONCE
            nonce = `TB_NONCE;
`elsif NONCE
            nonce = `NONCE;
`endif
            if      ($value$plusargs("nonce=%s",         nonce)) ;
            else if ($value$plusargs("NONCE=%s",         nonce)) ;
            else if ($value$plusargs("tb_nonce=%s",      nonce)) ;
            else if ($value$plusargs("TB_NONCE=%s",      nonce)) ;
            else if ($value$plusargs("verdict_nonce=%s", nonce)) ;
            else if ($value$plusargs("VERDICT_NONCE=%s", nonce)) ;
            else if ($value$plusargs("run_nonce=%s",     nonce)) ;
            else if ($value$plusargs("RUN_NONCE=%s",     nonce)) ;
        end
    endtask

    task advance_to(input integer target);
        begin
            while (ncount < target) begin
                @(negedge clk);
                ncount = ncount + 1;
            end
        end
    endtask

    task begin_frame(input [7:0] b, input hold_start);
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(negedge tx);
            if (!hold_start) start = 1'b0;
            ncount = 0;
        end
    endtask

    task sample_bit(input integer k);
        begin
            advance_to(k * CPB + CPB / 2);
            v = tx;
        end
    endtask

    task verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("TB_VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
                $finish;
            end
        end
    endtask

    task send_and_check_parity(input [7:0] b);
        begin
            begin_frame(b, 1'b0);
            sample_bit(9);
            checks = checks + 1;
            if (v !== (^b)) begin
                failed = failed + 1;
                $display("CHECK parity_even FAIL byte=%h got=%b expected=%b", b, v, ^b);
            end
            advance_to(14 * CPB);
        end
    endtask

    initial begin
        #500000;
        $display("CHECK watchdog FAIL: no verdict before timeout");
        failed = failed + 1;
        verdict;
    end

    initial begin
        get_nonce;
        rst = 1'b1;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (2 * CPB) @(negedge clk);

        send_and_check_parity(8'h00);
        send_and_check_parity(8'h01);
        send_and_check_parity(8'hFF);
        send_and_check_parity(8'h07);
        send_and_check_parity(8'h96);

        if (failed == 0) $display("CHECK parity_even PASS");
        verdict;
    end
endmodule
