// Repro for bucket B3 (frame_period_fail): the stop bit must last a full
// CLKS_PER_BIT cycles, so with start held high the next frame's start bit
// cannot begin before 11 bit-times after the previous start bit. Checks only
// the stop-bit window; data and parity values are not checked here.
`timescale 1ns / 1ps
module tb_uart_frame_tx_repro;
    localparam integer CPB = 4;

    reg        clk   = 1'b0;
    reg        rst   = 1'b1;
    reg        start = 1'b0;
    reg  [7:0] data  = 8'd0;
    wire       tx;
    wire       busy;

    integer    checks = 0;
    integer    failed = 0;
    integer    ncount = 0;
    integer    i;
    reg        verdict_done = 1'b0;
    reg [8*128-1:0] nonce;

    uart_frame_tx #(.CLKS_PER_BIT(CPB)) dut (
        .clk(clk), .rst(rst), .start(start), .data(data), .tx(tx), .busy(busy)
    );

    always #5 clk = ~clk;

    // Obtain the run nonce: a macro if defined, overridden by any known plusarg.
    task get_nonce;
        begin
            nonce = "unset";
`ifdef TB_NONCE
            nonce = `TB_NONCE;
`elsif NONCE
            nonce = `NONCE;
`endif
            if      ($value$plusargs("nonce=%s",         nonce)) ;
            else if ($value$plusargs("NONCE=%s",         nonce)) ;
            else if ($value$plusargs("tb_nonce=%s",      nonce)) ;
            else if ($value$plusargs("TB_NONCE=%s",      nonce)) ;
            else if ($value$plusargs("verdict_nonce=%s", nonce)) ;
            else if ($value$plusargs("VERDICT_NONCE=%s", nonce)) ;
            else if ($value$plusargs("run_nonce=%s",     nonce)) ;
            else if ($value$plusargs("RUN_NONCE=%s",     nonce)) ;
        end
    endtask

    task advance_to(input integer target);
        begin
            while (ncount < target) begin
                @(negedge clk);
                ncount = ncount + 1;
            end
        end
    endtask

    task begin_frame(input [7:0] b, input hold_start);
        begin
            @(negedge clk);
            data  = b;
            start = 1'b1;
            @(negedge tx);
            if (!hold_start) start = 1'b0;
            ncount = 0;
        end
    endtask

    task verdict;
        begin
            if (!verdict_done) begin
                verdict_done = 1'b1;
                $display("TB_VERDICT nonce=%0s checks=%0d failed=%0d", nonce, checks, failed);
                $finish;
            end
        end
    endtask

    initial begin
        #500000;
        $display("CHECK watchdog FAIL: no verdict before timeout");
        failed = failed + 1;
        verdict;
    end

    initial begin
        get_nonce;
        rst = 1'b1;
        repeat (4) @(posedge clk);
        @(negedge clk);
        rst = 1'b0;
        repeat (2 * CPB) @(negedge clk);

        // Hold start high: the next frame is requested as soon as the
        // transmitter is free, so a short stop bit lets it start early.
        begin_frame(8'h55, 1'b1);
        for (i = 10 * CPB + 1; i <= 11 * CPB; i = i + 1) begin
            advance_to(i);
            checks = checks + 1;
            if (tx !== 1'b1) begin
                failed = failed + 1;
                $display("CHECK stop_bit_length FAIL stop-bit cycle=%0d of %0d tx=%b expected=1",
                         i - 10 * CPB - 1, CPB, tx);
            end
        end
        @(negedge clk);
        start = 1'b0;
        repeat (16 * CPB) @(negedge clk);

        if (failed == 0) $display("CHECK stop_bit_length PASS");
        verdict;
    end
endmodule
